{
  "findings": [
    {
      "check_id": "CKV_GCP_11",
      "title": "Service account with overly permissive scope",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "HIGH",
      "explanation": "The service account is assigned the 'cloud-platform' scope, which grants full access to all Google Cloud APIs. This is overly permissive and increases the risk of privilege escalation or unintended access."
    },
    {
      "check_id": "CKV_GCP_62",
      "title": "Serial port access enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Enabling serial port access can expose the instance to unauthorized access if not properly secured. It is recommended to disable this unless explicitly required."
    },
    {
      "check_id": "CKV_GCP_67",
      "title": "Public IP assigned to instance",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "HIGH",
      "explanation": "The instance has an 'access_config' block, which assigns a public IP. This can expose the instance to the internet, increasing the attack surface."
    }
  ],
  "patched_code": "resource \"google_compute_instance\" \"backup_orchestration_engine\" {\n  name         = \"enterprise-disaster-recovery-orchestration-platform-compute-orchestration\"\n  machine_type = \"e2-medium\"\n  zone         = \"${var.primary_region}-a\"\n  boot_disk {\n    initialize_params {\n      image = \"debian-cloud/debian-11\"\n      size  = 50\n    }\n  }\n  network_interface {\n    network    = google_compute_network.dr_vpc.id\n    subnetwork = google_compute_subnetwork.management_subnet.id\n  }\n  service_account {\n    email  = \"123456789-compute@developer.gserviceaccount.com\"\n    scopes = [\"https://www.googleapis.com/auth/compute.readonly\"]\n  }\n  metadata = {\n    startup-script = file(\"${path.module}/scripts/orchestration-startup.sh\")\n  }\n  tags = [\"dr-internal\", \"orchestration-engine\"]\n  depends_on = [\n    google_storage_bucket.primary_backup_storage,\n    google_sql_database_instance.recovery_database\n  ]\n}",
  "fix_summary": "Restricted the service account scope to 'compute.readonly' to minimize permissions. Disabled serial port access by removing the 'serial-port-enable' metadata. Removed the 'access_config' block to prevent assignment of a public IP."
}
